const styles=new CSSStyleSheet;styles.replaceSync("/*\n * Copyright 2023 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n\n* {\n  margin: 0;\n  padding: 0;\n  box-sizing: border-box;\n  font-size: inherit;\n}\n\n*:focus,\n*:focus-visible {\n  outline: none;\n}\n\n.wrapper {\n  padding: 24px;\n}\n\n.header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 10px;\n}\n\nh1 {\n  font-size: 16px;\n  line-height: 19px;\n  color: var(--sys-color-on-surface);\n  font-weight: normal;\n}\n\n.icon,\n.icon devtools-icon {\n  width: 20px;\n  height: 20px;\n}\n\n.table {\n  margin-top: 35px;\n}\n\n.title {\n  font-size: 13px;\n  color: var(--sys-color-on-surface);\n  margin-left: 10px;\n  flex: 1;\n  overflow-x: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.row {\n  display: flex;\n  align-items: center;\n  padding-right: 5px;\n  height: 28px;\n  border-bottom: 1px solid var(--sys-color-divider);\n}\n\n.row:focus-within,\n.row:hover {\n  background-color: var(--sys-color-state-hover-on-subtle);\n}\n\n.row:last-child {\n  border-bottom: none;\n}\n\n.actions {\n  display: flex;\n  align-items: center;\n}\n\n.actions button {\n  border: none;\n  background-color: transparent;\n  width: 24px;\n  height: 24px;\n  border-radius: 50%;\n}\n\n.actions .divider {\n  width: 1px;\n  height: 17px;\n  background-color: var(--sys-color-divider);\n  margin: 0 6px;\n}\n\n/*# sourceURL=recordingListView.css */\n");export default styles;